/* ======== round 2 (2026-09-29): Comeback Cards, calm Fact Sprint, Book Club ======== */
/* ---------- Comeback Cards (spaced review, Leitner boxes). Shared API with Dino Star Patrol. ---------- */
const REVIEW_DAYS=[1,3,7,14,30],REVIEW_MAX=300,REVIEW_BYTES=90000,STATE_SOFT=200000;
function addDays(n){const d=new Date();d.setDate(d.getDate()+n);return dstr(d)}
function hashS(s){s=String(s);let h=5381;for(let i=0;i<s.length;i++)h=((h<<5)+h+s.charCodeAt(i))|0;return(h>>>0).toString(36)}
function reviewKey(skill,q){return(skill==='spell'&&q&&q.word)?'spell|'+String(q.word).toLowerCase():skill+'|'+hashS(qKey(q))}
function reviewSnap(skill,q){if(skill==='spell'&&q.word)return{word:q.word};const o={};['type','prompt','sub','fig','answer','explain','hint','pre','unit','big','level','word','sentPlain'].forEach(k=>{const v=q[k];if(v!==undefined&&v!==null&&v!=='')o[k]=v});if(Array.isArray(q.choices))o.choices=q.choices.map(c=>({h:c.h,ok:!!c.ok}));return o}
function reviewTrim(budget=REVIEW_BYTES){const R=S.review;let bytes=JSON.stringify(R).length,g=0;
 while((R.length>REVIEW_MAX||bytes>budget)&&R.length>1&&g++<600){let vi=0;for(let i=1;i<R.length;i++){const a=R[i],b=R[vi],sa=(a.box>5?100:0)+a.box,sb=(b.box>5?100:0)+b.box;if(sa>sb||(sa===sb&&String(a.added)<String(b.added)))vi=i}bytes-=JSON.stringify(R[vi]).length+1;R.splice(vi,1)}}
function reviewAdd(skill,q){try{if(!S||!q||!SK[skill])return null;S.review=S.review||[];const key=reviewKey(skill,q);let it=S.review.find(x=>x.key===key);
 if(it){it.box=1;it.due=addDays(REVIEW_DAYS[0])}else{it={key,skill,q:reviewSnap(skill,q),box:1,due:addDays(REVIEW_DAYS[0]),added:today(),wins:0};S.review.push(it);reviewTrim()}return it}catch(e){console.warn('reviewAdd',e);return null}}
/* a word that left the Spelling Splash list comes back once more after `days` */
function reviewRecheck(skill,q,days){try{if(!S||!q)return;S.review=S.review||[];const key=reviewKey(skill,q),it=S.review.find(x=>x.key===key);if(it){if(it.box>5){it.box=4;it.due=addDays(days)}return}
 S.review.push({key,skill,q:reviewSnap(skill,q),box:4,due:addDays(days),added:today(),wins:0,recheck:1});reviewTrim()}catch(e){console.warn('reviewRecheck',e)}}
function reviewDue(n=5){const t=today();const due=(S.review||[]).filter(x=>x&&x.box<=5&&x.due&&x.due<=t&&SK[x.skill]).sort((a,b)=>a.due<b.due?-1:a.due>b.due?1:String(a.added)<String(b.added)?-1:1);
 const by={};due.forEach(x=>(by[x.skill]=by[x.skill]||[]).push(x));const order=Object.keys(by).sort((a,b)=>by[a][0].due<by[b][0].due?-1:by[a][0].due>by[b][0].due?1:0);const out=[];
 while(out.length<n&&order.some(k=>by[k].length))order.forEach(k=>{if(out.length<n&&by[k].length)out.push(by[k].shift())});return out}
function reviewResult(key,ok){const it=(S.review||[]).find(x=>x.key===key);if(!it)return null;const was=it.box;it.last=today();
 if(ok){it.wins=(it.wins||0)+1;it.box=Math.min(6,it.box+1);it.due=it.box<=5?addDays(REVIEW_DAYS[it.box-1]):null;if(it.box>=3&&!it.cq){it.cq=1;bump('conquered');const d=day();d.cq=(d.cq||0)+1}}
 else{it.box=1;it.due=addDays(REVIEW_DAYS[0])}
 save();return{box:it.box,was,conquered:!!(ok&&it.box>=3&&was<3),mastered:it.box>5}}
function reviewStats(){const R=S.review||[],t=today();let week=0;for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()-i);const x=S.days[dstr(d)];if(x&&x.cq)week+=x.cq}
 const waiting=R.filter(x=>x.box<=5),by={};waiting.forEach(x=>{by[x.skill]=(by[x.skill]||0)+1});
 return{conq:Math.max((S.stats&&S.stats.conquered)||0,R.filter(x=>x.box>=3).length),week,waiting:waiting.length,due:waiting.filter(x=>x.due&&x.due<=t).length,by}}
function reviewQ(it){let q;if(it.skill==='spell'&&it.q&&it.q.word){if(!SPELL.some(x=>x.w===it.q.word))return null;q=mk('spell',S.skills.spell.level,it.q.word)}
 else{if(!it.q||!it.q.type||!it.q.prompt)return null;q=JSON.parse(JSON.stringify(it.q));if(Array.isArray(q.choices))q.choices=shuffle(q.choices)}q.skill=it.skill;q._rk=it.key;return q}
/* opens the day's first station with a short warm-up when cards are due */
function reviewGate(st){try{if(!S||!placedAll())return false;const d=day();if(d.review)return false;const items=reviewDue(5);if(!items.length)return false;renderReviewIntro(st,items);return true}catch(e){console.warn('reviewGate',e);return false}}
function renderReviewIntro(st,items){screen='review-intro';hush();const nm=(STATIONS.find(x=>x.id===st)||{name:'your mission'}).name,n=items.length;const intro='These are ones that tripped you up before — let’s see if they stick!';
 const areas=[...new Set(items.map(x=>AREA_NAME[SK[x.skill].area]))];
 app.innerHTML=`${topbar()}<div class="box center-card rv-intro"><div class="rv-cards" aria-hidden="true">${items.map((x,i)=>`<span class="rv-card" style="--r:${((i-(n-1)/2)*8).toFixed(1)}deg">${ICON.star}</span>`).join('')}</div>
 <h1>Comeback Cards</h1><p class="rv-say">${intro} ${sayBtn(intro)}</p><div class="row center">${areas.map(a=>`<span class="tag">${a}</span>`).join('')}</div>
 <p class="muted" style="margin:0">${pl(n,'card')} to warm up · then ${esc(nm)}</p><button class="btn teal" data-act="rv-go" data-st="${st}">Let’s go ${ICON.arrow}</button></div>`;
 drawAll();wireGate();say(['Comeback Cards!',300,intro.replace('—',',')])}
function startReview(st){const items=reviewDue(5),qs=[];items.forEach(it=>{let q=null;try{q=reviewQ(it)}catch(e){q=null}if(q)qs.push(q);else S.review=S.review.filter(x=>x!==it)});
 if(!qs.length){day().review=true;save();return startStation(st,true)}
 RUN={mode:'review',next:st,title:'Comeback Cards',results:[],used:new Set(),earned:0,ups:[],lastT:Date.now(),missed:[],rv:{n:0,ok:0,cq:0},
  planner:{total:qs.length,i:0,pos(){return this.i-(RUN.q&&!RUN.locked?1:0)},next(){return this.i<qs.length?qs[this.i++]:null},result(){}}};nextQ()}
function reviewAnswer(q,ok){RUN.locked=true;const r=reviewResult(q._rk,ok)||{};RUN.rv.n++;addTime();
 if(ok){RUN.rv.ok++;if(r.conquered)RUN.rv.cq++;gain(2);RUN.earned+=2;const hc=$('#hc');if(hc)hc.textContent=S.hearts;sfx.good();buddyJump();const c=$('.qcard');if(c){const b=c.getBoundingClientRect();burst(b.left+b.width/2,b.top+120,r.conquered?40:22)}
  const head=r.mastered?'Mastered for good!':r.conquered?'Mistake conquered!':'It stuck!';const sub=r.mastered?'This card is retired. Amazing memory!':r.conquered?'You got this one right again and again. It’s yours now!':'This card goes back in the deck and comes back later.';
  showFb('good',`<b>${head}</b><div>${sub}</div><span class="plus">+2 ${ICON.heart}</span>`);say([head,300,sub]);save();qLater(1700);return}
 if(q.type==='spell'&&RUN.lastTyped){sfx.bad();showFb('teach',`<b>Not quite. This one will come back tomorrow.</b><div>You wrote: <b>${esc(RUN.lastTyped)}</b><br>Correct: <b style="font-size:26px;letter-spacing:.06em">${spellMark(RUN.lastTyped,q.answer)}</b> <span class="muted">(highlighted letters are the tricky part)</span></div><div class="exp">${q.explain||''}</div><button class="btn teal" data-act="next">Got it ${ICON.arrow}</button>`);say(['Not quite.',300,'It is spelled',[...q.answer].join(', '),500,String(q.explain||'').replace(/<[^>]+>/g,' ')]);return}
 showMiss(q);const f=$('#fb b');if(f)f.insertAdjacentHTML('afterend','<div class="muted">No worries. This card comes back tomorrow.</div>')}
function reviewDone(){screen='summary';const d=day();d.review=true;addTime();save();const rv=RUN.rv,st=RUN.next,nx=STATIONS.find(x=>x.id===st);
 const all=rv.ok===rv.n;const msg=all?'Every card stuck. Your brain is getting stronger!':rv.ok?'The tricky ones come back tomorrow. Each try makes them stick better.':'That’s okay! These come back tomorrow, and each try helps them stick.';
 app.innerHTML=`${topbar()}<div class="box center-card">${spr(S.current||'owl','lg','bob')}<h1>${all?'They all stuck!':'Warm-up done!'}</h1>
 <div class="bigstats"><div class="bigstat"><b>${rv.ok}/${rv.n}</b><span>remembered</span></div>${rv.cq?`<div class="bigstat"><b>${rv.cq}</b><span>mistakes conquered</span></div>`:''}<div class="bigstat"><b>+${RUN.earned}</b><span>hearts</span></div></div>
 <p style="margin:0">${msg}</p><div class="row center">${nx?`<button class="btn teal" data-act="rv-next" data-st="${nx.id}">Now: ${nx.name} ${ICON.arrow}</button>`:''}<button class="btn ghost" data-act="go-home">Back to the Cove</button></div></div>`;
 drawAll();wireGate();if(rv.cq){sfx.win();burst()}say([all?'They all stuck!':'Warm-up done!',300,msg])}
function reviewDashHTML(){const r=reviewStats();const skills=Object.entries(r.by).sort((a,b)=>b[1]-a[1]);
 return`<section class="box panel"><h2>Comeback Cards (spaced review)</h2><div class="kpis"><div class="kpi"><b>${r.conq}</b><span>mistakes conquered</span></div><div class="kpi"><b>${r.week}</b><span>conquered this week</span></div><div class="kpi"><b>${r.waiting}</b><span>waiting to come back</span></div><div class="kpi"><b>${r.due}</b><span>due today</span></div></div>
 ${skills.length?`<div class="wchips" style="margin-top:12px">${skills.map(([k,n])=>`<span class="wchip">${esc(SK[k]?SK[k].name:k)} <span class="muted">×${n}</span></span>`).join('')}</div>`:''}
 <p class="note">Every first-try miss becomes a card. Cards come back 1, 3, 7, 14 and 30 days later; a right answer moves a card up a box and a miss sends it back to day 1. “Conquered” means she got it right on at least two spaced comebacks. Words that leave the spelling list are checked once more after 14 days.</p>${sprintDashHTML()}</section>`}
function sprintDashHTML(){const L=(S.sprintLog||[]).slice(-8);if(!L.length)return'';const fpm=x=>x.sec?Math.round(x.score/(x.sec/60)*10)/10:x.score;
 return`<p style="margin:14px 0 4px"><b>Fact Sprint</b> <span class="muted">(parents only: she never sees a clock)</span></p><div class="wchips">${L.map(x=>`<span class="wchip">${esc(x.d.slice(5))}: ${x.score} right · ${fpm(x)}/min</span>`).join('')}</div><p class="note">Best: ${S.best.sprint} right in one round.</p>`}

/* keep the main state doc well under the 256 KiB db limit as logs grow over a school year */
function stateCompact(){if(!S)return;const size=()=>JSON.stringify(S).length;if(size()<=STATE_SOFT)return;
 if(S.writing&&S.writing.length>8)S.writing=S.writing.slice(-8);if(size()<=STATE_SOFT)return;if(S.review)reviewTrim(60000);if(size()<=STATE_SOFT)return;
 const all=[];(S.books||[]).forEach(b=>b.log.forEach(e=>all.push(e)));all.sort((a,b)=>String(a.date)<String(b.date)?-1:1);
 for(const e of all){if(e.qs&&e.qs.length)e.qs=e.qs.map(x=>({q:String(x.q).slice(0,80),a:String(x.a).slice(0,120)}));if(e.story&&e.story.length>300)e.story=e.story.slice(0,297)+'…';if(Array.isArray(e.stories))e.stories=e.stories.map(x=>x.length>300?x.slice(0,297)+'…':x);if(size()<=STATE_SOFT)return}
 if(S.review)reviewTrim(30000)}
{const __save1=save;save=function(){try{stateCompact()}catch(e){console.warn('compact',e)}__save1()}}
/* ---------- Fact Sprint: calm progress path (no visible clock) ---------- */
function spPathHTML(){const best=RUN.prevBest||0,sc=RUN.score||0;const n=Math.min(40,Math.max(12,best+3,sc+2));let h='';for(let i=1;i<=n;i++){const isB=best>0&&i===best;h+=`<i class="${i<=sc?'on':''}${isB?' best':''}">${isB?`<b>${ICON.star}</b>`:''}</i>`}return h}
function spUpdate(){const p=$('#sppath');if(p)p.innerHTML=spPathHTML();const a=$('#sans');if(a)a.textContent=RUN.n;const s=$('#sscore');if(s)s.textContent=RUN.score;
 if(RUN.prevBest>0&&RUN.score===RUN.prevBest+1&&!RUN.pbToast){RUN.pbToast=true;toast(`New personal best! ${ICON.star}`)}}

