/* ---------- Book Club: grounding check (never let the AI invent plot facts) ---------- */
const BC_OK=new Set(('I What What’s Why How Who Whose Where When Which Do Does Did Is Are Was Were Can Could Would Will Should If You You’re Your Yours In The A An This That These Those Think Imagine Pick Find Tell Describe Have Has Had Look Name Predict Compare Explain Choose Write Use Say Let Since After Before At On Now So And But Maybe Wow Great Nice Good Awesome Super Yes Hmm Remember Picture Pretend Suppose Based Some Many Any It It’s Its Try Then Next First Also Another Keep Love Way Cool Fantastic Wonderful Excellent Thanks Thank Brilliant Beautiful Oh Neat Ready Here There Even Just Not No Being Words Word Sentence Something Someone Everyone Because For From With To Of By As All Each Every One Two Three My We Our Me Glow Grow Adding Add Next Reading Readers Good Strong Clear Clearly Smart Lovely Terrific Perfect Well Sounds Such Most More Very Really Wonderful Great').split(' '));
function bcGrounded(text,allowed){const A=String(allowed||''),set=new Set();(A.match(/[A-Za-z][A-Za-z’'-]*/g)||[]).forEach(w=>{set.add(w);set.add(w[0].toUpperCase()+w.slice(1))});
 const nums=new Set(A.match(/\d+/g)||[]);
 for(const sent of String(text).split(/(?<=[.!?:;])\s+|["“”]/)){const ws=sent.match(/[A-Za-z][A-Za-z’'-]*|\d+/g)||[];
  for(let i=0;i<ws.length;i++){const w=ws[i];if(/^\d/.test(w)){if(!nums.has(w))return false;continue}
   if(!/^[A-Z]/.test(w))continue;if(w==='I'||/^I[’'](m|d|ll|ve)$/.test(w))continue;if(set.has(w))continue;if(i===0&&BC_OK.has(w))continue;if(i>0&&(w==='Coach'||w==='Hoot'))continue;return false}}
 return true}

/* stricter check for any AI text shown in Book Club: every content word must be generic coaching language or come from her own words */
const BC_GEN=new Set(('about above after again also always another answer answers asked asking awesome back because been before beginning being best better big both brave bravely came careful change changed changes chapter chapters character characters choice choose chose clear clearer clearly clue clues come comes coming could creative curious decide decided decides describe described describing detail details did different does doing done ending even ever every exact exactly excited exciting explain explained explaining feel feeling feelings felt find finds first from fun funny going good great happen happened happening happens happy have help helped helps here how idea ideas imagine imaginative important instead interesting just keep kind know learn learned like liked likes little look looked looking love loved lovely made make makes maybe mean means might more most much must name named names need next nice notice noticed only other own part parts pick picked picture plan predict predicted prediction predictions problem question questions ready real really reason reasons remind reminds right said same says scared second sentence sentences should show showed shows smart some someone something sound sounds special story strong super sure surprise surprised surprising tell telling tells than thank thanks that their them then there these they thing things think thinking thought thoughtful those told together tried tries try trying very want wanted wants well were what when where which while who whole why will wish with wonder wonderful word words work would wow write writer writing wrote your yourself adventure adventures action add adding caps capital capitals period periods punctuation spelling spell spelled transition transitions vivid dialogue middle start starts started characters mistake mistakes excellent fantastic brilliant terrific proud nicely careful clever amazing cool cute sweet kindness friend friends friendship someone everyone anyone happened sure lots plus favorite moment moments').split(' '));
const bcStem=w=>w.toLowerCase().replace(/[’']s$/,'').replace(/(ing|ed|es|ly|s)$/,'');
const BC_BOOKREF=/\b(real|actual|original|whole|published) (book|story|novel)\b|\bin the (book|novel|series)\b|\bthe author (wrote|says|said)\b|\blater in the (book|story)\b/i;
function bcSafe(text,allowed){text=String(text||'');if(!text.trim()||BC_BOOKREF.test(text)||!bcGrounded(text,allowed))return false;const aw=new Set();(String(allowed).match(/[A-Za-z’']+/g)||[]).forEach(w=>{aw.add(w.toLowerCase());aw.add(bcStem(w))});
 for(const w of text.match(/[A-Za-z’']+/g)||[]){const l=w.toLowerCase();if(l.length<4||BC_GEN.has(l)||BC_GEN.has(bcStem(w))||aw.has(l)||aw.has(bcStem(w)))continue;return false}return true}
/* AI questions must quote her exact words (summary or page text) */
function bcQuoted(q,allowed){const norm=x=>String(x).toLowerCase().replace(/[’']/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim();const A=' '+norm(allowed)+' ';const qs=[...String(q).matchAll(/[“"]([^”"]{3,200})[”"]/g)].map(m=>norm(m[1]));return qs.length>0&&qs.every(x=>x.split(' ').length>=2&&A.includes(' '+x+' '))}
