const txtOn=c=>{const n=parseInt(c.slice(1),16),r=n>>16,g=n>>8&255,b=n&255;return(r*299+g*587+b*114)/1000>150?'#3d2c2e':'#ffffff'};
function wrapT(t,max,lines){const ws=String(t).split(/\s+/),out=[];let cur='';ws.forEach(w=>{if((cur+' '+w).trim().length>max&&cur){out.push(cur);cur=w}else cur=(cur+' '+w).trim()});if(cur)out.push(cur);if(out.length>lines){out.length=lines;out[lines-1]=out[lines-1].replace(/.{0,2}$/,'…')}return out}
function spineSVG(b){const h=150+(parseInt(hashS(b.title||'x'),36)%5)*7,c=b.color||'#4c8dff',l=shade(c,.4),t=b.title.length>22?b.title.slice(0,21)+'…':b.title,tc=txtOn(c);
 return`<svg class="spine" viewBox="0 0 48 ${h}" width="48" height="${h}" aria-hidden="true"><rect x="3" y="2" width="42" height="${h-4}" rx="7" fill="${c}" stroke="${OL}" stroke-width="2.5"/><rect x="4.5" y="15" width="39" height="6" fill="${l}" opacity=".85"/><rect x="4.5" y="${h-24}" width="39" height="6" fill="${l}" opacity=".85"/><rect x="8" y="4" width="5" height="${h-8}" rx="2" fill="#fff" opacity=".2"/><text transform="translate(28.5 ${h/2}) rotate(-90)" text-anchor="middle" dominant-baseline="middle" font-family="Lexend,sans-serif" font-weight="700" font-size="11.5" fill="${tc}">${esc(t)}</text>${b.done?star5(24,h-11,7,'#ffc53d'):''}</svg>`}
