 if(!revising){e={ch:d.ch,date:today(),summary:text.slice(0,1500),qs:[],art:false,story:null,artId:null,arts:[],stories:[]};if(hand)e.hand=true;b.log.push(e);d.ent=b.log.length-1;S.bookCur=b.id;
  gain(BC_REWARD.log);const dd=day();dd.book=true;dd.bookN=(dd.bookN||0)+1;toast(`+${BC_REWARD.log} hearts for logging chapter ${d.ch}!${placedAll()&&!dd.done.write?' It counts as today’s writing.':''}`);sfx.good();burst(innerWidth/2,innerHeight*.35,24)}
 else{e=b.log[d.ent];if(e){e.summary=text.slice(0,1500);if(!e.rev){e.rev=true;gain(BC_REWARD.rev);toast(`+${BC_REWARD.rev} bonus hearts for revising!`)}sfx.good()}}
 if(hand&&hwUrl&&e){const id=e.hwId||('hw'+Date.now().toString(36)+rnd(100,999));e.hwId=id;artSave(id,{kind:'hw',book:b.id,ch:e.ch,date:e.date},hwUrl)}
