 BC.post=()=>{$$('.bc-ans').forEach(ta=>ta.addEventListener('input',()=>{t.ans[+ta.dataset.i]=ta.value}));$$('.bc-word').forEach(inp=>inp.addEventListener('input',()=>{t.words[+inp.dataset.i]=inp.value}))};
