const DR_COLORS=[['#2b2233','Black'],['#e8483a','Red'],['#ff9f1c','Orange'],['#ffd23f','Yellow'],['#3fbf6a','Green'],['#2b8cff','Blue'],['#8f6bff','Purple'],['#ff8fb3','Pink'],['#8b5a2b','Brown']];
const DR_SIZES=[[.006,'Thin pen'],[.014,'Medium pen'],[.03,'Thick pen']];
function drStroke(ctx,s,W,from){const p=s.pts;ctx.save();ctx.strokeStyle=s.c;ctx.fillStyle=s.c;ctx.lineWidth=s.w*W;ctx.lineCap='round';ctx.lineJoin='round';
 if(p.length===1){ctx.beginPath();ctx.arc(p[0].x*W,p[0].y*W,s.w*W/2,0,6.283);ctx.fill()}else{const f=Math.max(0,from);ctx.beginPath();ctx.moveTo(p[f].x*W,p[f].y*W);for(let i=f+1;i<p.length;i++)ctx.lineTo(p[i].x*W,p[i].y*W);ctx.stroke()}ctx.restore()}
function drRedraw(){const c=$('#drc');if(!c||!BC.make)return;const ctx=c.getContext('2d'),W=c.clientWidth,H=c.clientHeight;ctx.fillStyle='#fff';ctx.fillRect(0,0,W,H);BC.make.strokes.forEach(s=>drStroke(ctx,s,W,0))}
function drInit(){const w=$('#drwrap'),c=$('#drc'),M=BC.make;if(!c||!M)return;const dpr=window.devicePixelRatio||1;c.width=Math.round(w.clientWidth*dpr);c.height=Math.round(w.clientHeight*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);drRedraw();
 const pt=e=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.width}};let cur=null;
 c.onpointerdown=e=>{if(e.pointerType==='pen')M.penSeen=true;else if(e.pointerType==='touch'&&M.penSeen)return;e.preventDefault();try{c.setPointerCapture(e.pointerId)}catch(_){}const er=M.tool==='eraser';cur={c:er?'#ffffff':M.color,w:er?Math.max(.035,M.size*1.8):M.size,pts:[pt(e)]};M.strokes.push(cur);drStroke(ctx,cur,c.clientWidth,0);const h=$('#drhint');if(h)h.hidden=true};
 c.onpointermove=e=>{if(!cur)return;e.preventDefault();const s=cur.pts.length-1;const evs=e.getCoalescedEvents?e.getCoalescedEvents():[e];(evs.length?evs:[e]).forEach(ev=>cur.pts.push(pt(ev)));drStroke(ctx,cur,c.clientWidth,s)};
 c.onpointerup=c.onpointercancel=()=>{cur=null}}
function drExport(){const M=BC.make;const mk=(w,q)=>{const h=Math.round(w*.75),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);M.strokes.forEach(s=>drStroke(x,s,w,0));return c.toDataURL('image/jpeg',q)};
 let w=700,q=.6,u=mk(w,q);while(u.length>80000&&q>.35){q=Math.round((q-.1)*10)/10;u=mk(w,q)}while(u.length>80000&&w>320){w=Math.round(w*.8);u=mk(w,.45)}return u}
